-- H-133: ejecución única del manifiesto vivo sellado.
-- manifest_sha256=5e7193f0e7718fc9e92a17302041e042a55982b56f5e59742f8930900a50dab2
-- analyzer_sha256=07240bfd92c9d5389f23f131c140e4e46218cdc09bee5f882f69bbfc5ef56e11
-- source_products=357; migrated=831; existing_v2=138
begin;

do $h133_execution$
begin
  -- Una instalación limpia no contiene el snapshot vivo sellado. Activa el
  -- contrato vacío sin fingir que ejecutó la operación de producción; si hay
  -- cualquier inventario, el manifiesto exacto sigue siendo obligatorio.
  if not exists(select 1 from pos.products where deleted_at is null) then
    update pos.inventory_contract_state
       set contract_version=3,enforced=true,operation_id=null,
           manifest_hash='EMPTY_INVENTORY_V3',activated_at=now(),updated_at=now()
     where singleton;
    update pos.system_manifest
       set data_epoch=data_epoch+1,sync_protocol_min=3,sync_protocol_current=3,
           schema_version=greatest(schema_version,20260830017300),updated_at=now()
     where singleton;
    return;
  end if;

